import React,{useState}from'react';import{createRoot}from'react-dom/client';
type Contact={name:string,email:string};
function parse(text:string):Contact[]{const rows:string[][]=[];let row:string[]=[];let value='';let quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){value+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(Boolean))rows.push(row);row=[];value='';}else value+=c;}row.push(value);if(row.some(Boolean))rows.push(row);if(quote)throw Error('Unclosed CSV quote');if(rows[0]?.map(x=>x.trim().toLowerCase()).join(',')!=='name,email')throw Error('Expected name,email header');return rows.slice(1).map(values=>({name:(values[0]??'').trim(),email:(values[1]??'').trim()}));}
const encode=(value:string)=>/[",\n\r]/.test(value)?`"${value.replaceAll('"','""')}"`:value;
const valid=(row:Contact)=>row.name.length>0&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(row.email);
function App(){const saved=()=>{try{return JSON.parse(localStorage.getItem('alternative-contacts')??'[]')as Contact[];}catch{return[];}};const[rows,setRows]=useState<Contact[]>(saved);const[input,setInput]=useState('');const[query,setQuery]=useState('');const[output,setOutput]=useState('');const[status,setStatus]=useState('');
const update=(index:number,key:keyof Contact,value:string)=>setRows(rows.map((row,i)=>i===index?{...row,[key]:value}:row));const matches=rows.filter(row=>`${row.name} ${row.email}`.toLowerCase().includes(query.toLowerCase()));
return <main><h1>Contact import</h1><label>CSV data<textarea value={input}onChange={e=>setInput(e.target.value)}/></label><button onClick={()=>{try{setRows(parse(input));setStatus('Imported draft');setOutput('');}catch(e){setStatus(String(e));}}}>Import</button><p role="status">{status}</p><section aria-label="Imported contacts">{rows.map((row,index)=><article key={index}><label>Name {index+1}<input value={row.name}onChange={e=>update(index,'name',e.target.value)}/></label><label>Email {index+1}<input value={row.email}onChange={e=>update(index,'email',e.target.value)}/></label>{!valid(row)&&<p role="alert">Invalid name or email in row {index+1}</p>}</article>)}</section><button disabled={!rows.length||!rows.every(valid)}onClick={()=>{localStorage.setItem('alternative-contacts',JSON.stringify(rows));setStatus('Saved');}}>Save</button><label>Filter<input value={query}onChange={e=>setQuery(e.target.value)}/></label><section aria-label="Filtered contacts"><h2>Results</h2>{matches.map((row,index)=><p key={index}>{row.name} — {row.email}</p>)}</section><button onClick={()=>{const data=['name,email',...matches.map(row=>`${encode(row.name)},${encode(row.email)}`)].join('\n');const url=URL.createObjectURL(new Blob([data],{type:'text/csv'}));const link=document.createElement('a');link.href=url;link.download='contacts.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}>Export</button></main>;
}createRoot(document.getElementById('root')!).render(<App/>);
